/**
 * @method
 * @name scwin.tx_fn_saveBubJohang
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_saveBubJohang = async function () {
    const sbmOptions = {
        id: "tx_fn_saveBubJohang",
        method: "post",
        action: "/ods/integsrchBase.do",
        ref: "dma_saveBubJohangReq",
        target: "dlt_junmoonList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf72010.tx_fn_saveBubJohang" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

